import{_ as a,C as t,o as n,c as p,k as o,a as s,H as l,Q as c}from"./chunks/framework.5916b37e.js";const C=JSON.parse('{"title":"升级到 4.0","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/upgrading-to-4.md","filePath":"zh/guide/upgrading-to-4.md"}'),r={name:"zh/guide/upgrading-to-4.md"},d={id:"升级到-4-0",tabindex:"-1"},i=o("a",{class:"header-anchor",href:"#升级到-4-0","aria-label":'Permalink to "升级到 4.0 <Badge type="warning" text="破坏性变更" />"'},"​",-1),u=c(`<p>4.0.0 是一次<strong>打包方式</strong>的发布。copper3d 的 API 本身没有变 —— 3.11.x 里的每一个类、方法和类型 都和原来一样。变的是 <strong>three.js 以什么方式到达你手里</strong>，而这需要你这边改一下。</p><h2 id="唯一必须做的改动" tabindex="-1">唯一必须做的改动 <a class="header-anchor" href="#唯一必须做的改动" aria-label="Permalink to &quot;唯一必须做的改动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">npm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">install</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">copper3d</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">three@~0.186.0</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">npm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">install</span><span style="color:#24292E;"> </span><span style="color:#032F62;">copper3d</span><span style="color:#24292E;"> </span><span style="color:#032F62;">three@~0.186.0</span></span></code></pre></div><p><code>three</code> 现在是<strong>对等依赖（peer dependency）</strong>。以前是 copper3d 依赖 three 并把它打进包里； 现在由你来安装，copper3d 共用你那一份。</p><p>TypeScript 用户还需要类型，它是一个<em>可选</em>的对等依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">npm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">install</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">-D</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">@types/three@~0.186.0</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">npm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">install</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">-D</span><span style="color:#24292E;"> </span><span style="color:#032F62;">@types/three@~0.186.0</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">为什么要改成 peer 而不是打包进去</p><p>打包进去会让页面上出现两份 three。three 自己会就此告警 —— <em>&quot;Multiple instances of Three.js being imported&quot;</em> —— 而实际后果比这条告警严重得多： 你代码里构造出来的 <code>Mesh</code>，<strong>不是</strong> copper3d 用来判断的那个 <code>Mesh</code> 的 <code>instanceof</code>， 因为它们来自不同的模块。任何跨越这条边界传递的东西 —— 相机、场景、几何体 —— 都得面对这个问题。</p><p>改成对等依赖之后，页面上就只有一份 three，对象可以自由穿过边界。</p></div><h2 id="其他变化" tabindex="-1">其他变化 <a class="header-anchor" href="#其他变化" aria-label="Permalink to &quot;其他变化&quot;">​</a></h2><table><thead><tr><th></th><th>3.11.x</th><th>4.0.0</th></tr></thead><tbody><tr><td>three</td><td>打包进来的 dependency，<code>^0.185.1</code></td><td><strong>peer</strong> dependency，<code>~0.186.0</code></td></tr><tr><td><code>@types/three</code></td><td>dependency</td><td>可选 peer，<code>~0.186.0</code></td></tr><tr><td>ESM 产物</td><td><code>dist/bundle.esm.js</code></td><td><code>dist/bundle.esm.mjs</code></td></tr><tr><td><code>package.json</code> 的 <code>module</code> 字段</td><td><code>&quot;moudle&quot;</code>（<strong>拼错了</strong>，从来没生效过）</td><td><code>&quot;module&quot;</code>，并新增了真正的 <code>exports</code> map</td></tr><tr><td>three addon 的导入路径</td><td><code>three/examples/jsm/…</code></td><td><code>three/addons/…</code></td></tr></tbody></table><h3 id="exports-map" tabindex="-1"><code>exports</code> map <a class="header-anchor" href="#exports-map" aria-label="Permalink to &quot;\`exports\` map&quot;">​</a></h3><p><code>package.json</code> 现在声明了一份：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;exports&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;.&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#E1E4E8;">      </span><span style="color:#79B8FF;">&quot;types&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/types/index.d.ts&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">      </span><span style="color:#79B8FF;">&quot;import&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/bundle.esm.mjs&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">      </span><span style="color:#79B8FF;">&quot;require&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/bundle.umd.js&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">    },</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;./dist/css/*&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/css/*&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;./package.json&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./package.json&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;exports&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;.&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;types&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/types/index.d.ts&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;import&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/bundle.esm.mjs&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;require&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/bundle.umd.js&quot;</span></span>
<span class="line"><span style="color:#24292E;">    },</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;./dist/css/*&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/css/*&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;./package.json&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./package.json&quot;</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p><code>import</code> 和 <code>require</code> 现在会自动解析到正确的产物。ESM 文件用 <code>.mjs</code> 后缀，这样 Node 不需要包里 声明 <code>&quot;type&quot;: &quot;module&quot;</code> 也能按 ESM 加载它。</p><div class="warning custom-block"><p class="custom-block-title">深层导入不再可用</p><p><code>exports</code> map 是一道边界。如果你以前是伸手进包里取文件的 —— <code>import … from &quot;copper3d/dist/bundle.esm.js&quot;</code> —— 现在会解析不到。请从包根导入；样式表则从 <code>copper3d/dist/css/...</code> 导入。</p></div><h3 id="你的-tsconfig-里的-moduleresolution" tabindex="-1">你的 tsconfig 里的 <code>moduleResolution</code> <a class="header-anchor" href="#你的-tsconfig-里的-moduleresolution" aria-label="Permalink to &quot;你的 tsconfig 里的 \`moduleResolution\`&quot;">​</a></h3><p>copper3d 通过 <code>three/addons/*</code> 导入 three 的 addon，而 three <strong>只</strong>通过它的 <code>exports</code> map 暴露这些路径。TypeScript 传统的 <code>&quot;node&quot;</code> 解析策略早于 exports map，跟不进这些路径。所以如果你的 <code>tsconfig.json</code> 写的是：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{ </span><span style="color:#79B8FF;">&quot;compilerOptions&quot;</span><span style="color:#E1E4E8;">: { </span><span style="color:#79B8FF;">&quot;moduleResolution&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;node&quot;</span><span style="color:#E1E4E8;"> } }</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{ </span><span style="color:#005CC5;">&quot;compilerOptions&quot;</span><span style="color:#24292E;">: { </span><span style="color:#005CC5;">&quot;moduleResolution&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;node&quot;</span><span style="color:#24292E;"> } }</span></span></code></pre></div><p>请改成 <code>&quot;bundler&quot;</code>（Vite、webpack、Rollup）或 <code>&quot;node16&quot;</code> / <code>&quot;nodenext&quot;</code>（Node）。继续用 <code>&quot;node&quot;</code> 还意味着 TypeScript 会忽略 copper3d 自己的 <code>exports</code> map，可能根本找不到它的类型。</p><h3 id="版本一致性检查" tabindex="-1">版本一致性检查 <a class="header-anchor" href="#版本一致性检查" aria-label="Permalink to &quot;版本一致性检查&quot;">​</a></h3><p>在 import 时，copper3d 会把<strong>构建时</strong>所针对的 three 版本和<strong>实际加载</strong>的那一份做比较，不一致就 打印一条 <code>console.error</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">copper3d was built against three r186, but three r180 is loaded.</span></span>
<span class="line"><span style="color:#e1e4e8;">Install the three version copper3d&#39;s peerDependencies name.</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">copper3d was built against three r186, but three r180 is loaded.</span></span>
<span class="line"><span style="color:#24292e;">Install the three version copper3d&#39;s peerDependencies name.</span></span></code></pre></div><p>npm 在安装阶段就会拒绝不兼容的 peer，但 yarn 1 和 pnpm 只是告警 —— 而 three 在小版本之间也会改 行为，所以这个不一致值得放在一个划不过去的地方再说一遍。该检查<strong>不会抛异常</strong>，只是报告之后继续。</p><p>从源码构建、没有注入版本常量时，会跳过这次比较。</p><h2 id="哪些没有变" tabindex="-1">哪些<strong>没有</strong>变 <a class="header-anchor" href="#哪些没有变" aria-label="Permalink to &quot;哪些**没有**变&quot;">​</a></h2><ul><li>copper3d 的每一个类、方法、选项和类型。所有调用点都不需要改。</li><li><code>copperRenderer</code>、<code>copperScene</code>、<code>NrrdTools</code>、各个 loader、分割引擎。</li><li>UMD 产物仍然在 <code>dist/bundle.umd.js</code>，只是现在把 <code>three</code> 映射到了 <code>THREE</code> 这个全局变量。</li></ul><div class="tip custom-block"><p class="custom-block-title">UMD 产物是给 <code>require</code> 用的，不是给 <code>&lt;script&gt;</code> 标签用的</p><p>只有 three 的<strong>核心</strong>有浏览器全局变量。<code>three/addons/*</code> 没有，所以一个裸的 script 标签无法满足 copper3d 对 addon 的导入。请使用打包器，或者用 ESM 产物。</p></div><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><ol><li><code>npm install copper3d three@~0.186.0</code>（TypeScript 还要 <code>-D @types/three@~0.186.0</code>）。</li><li>如果 <code>tsconfig.json</code> 里是 <code>&quot;moduleResolution&quot;: &quot;node&quot;</code>，改掉。</li><li>把任何对 <code>copper3d/dist/...</code> 的深层导入改成从包根导入。</li><li>把应用跑起来一次，看控制台有没有那条版本不一致的报错。</li></ol><p>就这些。第 4 步安静、项目能构建，就升级完成了。</p>`,29);function y(E,h,q,g,m,b){const e=t("Badge");return n(),p("div",null,[o("h1",d,[s("升级到 4.0 "),l(e,{type:"warning",text:"破坏性变更"}),s(),i]),u])}const k=a(r,[["render",y]]);export{C as __pageData,k as default};
